package app.trace

import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedInputStream
import java.io.OutputStream
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.security.MessageDigest
import java.util.Base64
import java.util.concurrent.atomic.AtomicInteger
import app.trace.telemetry.WebAuth
import java.io.File
import java.net.URLDecoder
import kotlin.concurrent.thread
import kotlin.math.abs

/**
 * webui_server.py on the phone: the same read-only LAN dashboard page (assets/webui.html is the desktop page,
 * generated by tools/gen_android_webui.py) plus a WebSocket feed on the SAME port. Off by default; localhost only
 * until ALLOW REMOTE (WEB UI) is on, and then every page, route and the /ws feed needs the passcode ([WebAuth]: the
 * 6-digit code, the QR link or a remembered device) -- except requests from the phone itself (127.0.0.1 / ::1).
 * Nothing leaves the local network. Needs only the INTERNET permission the app already declares.
 */
class WebUiServer(private val page: () -> ByteArray, private val loginPage: () -> ByteArray, devicesFile: File) {
    val auth = WebAuth(devicesFile)
    @Volatile private var remote = false
    @Volatile private var server: ServerSocket? = null
    private val clients = AtomicInteger(0)
    @Volatile private var seq = 0
    @Volatile private var json = ""
    @Volatile private var frameAt = 0L
    private val lock = Any()
    private val pts = ArrayDeque<Pair<Double, Double>>()
    private var trackVersion = 0
    private var trackKey: Pair<String, String>? = null
    private val laps = ArrayList<IntArray>()
    private var lastLapMs: Long? = null
    private var prevSpd: Pair<Double, Long>? = null
    private var smoothLong = 0.0
    @Volatile var lastError: String? = null; private set

    val running get() = server != null

    fun start(port: Int, remote: Boolean): Boolean {
        if (server != null) return true
        return try {
            val s = ServerSocket(port, 16, InetAddress.getByName(if (remote) "0.0.0.0" else "127.0.0.1"))
            this.remote = remote; auth.rotate()   // a fresh code and QR token every time the WEB UI is turned on
            server = s; lastError = null
            thread(isDaemon = true, name = "trace-webui") {
                while (!s.isClosed) {
                    try { val c = s.accept(); thread(isDaemon = true, name = "trace-webui-c") { handle(c) } } catch (_: Exception) { break }
                }
            }
            true
        } catch (e: Exception) { lastError = "${e.javaClass.simpleName}: ${e.message}"; false }
    }

    fun stop() {
        try { server?.close() } catch (_: Exception) {}
        server = null
        auth.end()   // turning the WEB UI off logs every device out of this session
        synchronized(lock) { pts.clear(); trackKey = null; laps.clear(); lastLapMs = null; json = ""; seq = 0 }
    }

    private fun num(v: Any?, d: Double = 0.0): Double = ((v as? Number)?.toDouble() ?: d).let { if (it.isNaN() || it.isInfinite()) d else it }
    private fun clean(v: String?) = (v ?: "").filter { !it.isISOControl() }.take(80)

    /** webui_server.update(): extras = connected, curMs, delta, vsTop, strategy, car, track. */
    fun update(d: Map<String, Any?>, connected: Boolean, curMs: Int?, delta: Double?, vsTop: Double?, st: app.trace.telemetry.StintTracker.Snapshot?, car: String, track: String) {
        if (server == null) return
        try {
            synchronized(lock) {
                val last = (d["last_lap_ms"] as? Number)?.toLong()
                if (last != null && last > 0 && last != lastLapMs) {
                    laps.add(intArrayOf(num(d["lap_number"]).toInt() - 1, last.toInt()))
                    while (laps.size > 50) laps.removeAt(0)
                }
                lastLapMs = last
                val key = car to track
                if (key != trackKey) { pts.clear(); laps.clear(); trackKey = key; trackVersion++ }
                val x = num(d["world_x"]); val z = num(d["world_z"])
                if ((x != 0.0 || z != 0.0) && num(d["speed_kmh"]) > 1) {
                    if (pts.isNotEmpty() && (abs(x - pts.last().first) > 80 || abs(z - pts.last().second) > 80)) { pts.clear(); trackVersion++ }
                    if (pts.isEmpty() || abs(x - pts.last().first) > 1.0 || abs(z - pts.last().second) > 1.0) {
                        pts.addLast(Math.round(x * 10) / 10.0 to Math.round(z * 10) / 10.0)
                        if (pts.size > 3000) pts.removeFirst()
                    }
                }
                val spd = num(d["speed_kmh"]); val now = System.nanoTime()
                var lg = 0.0
                prevSpd?.let { (ps, pt) ->
                    if (now > pt) {
                        lg = ((spd - ps) / 3.6 / ((now - pt) / 1e9) / 9.81).coerceIn(-4.0, 4.0)
                        lg = 0.6 * lg + 0.4 * smoothLong
                    }
                }
                prevSpd = spd to now; smoothLong = lg
                json = frame(d, spd, lg, connected, curMs, delta, vsTop, st, car, track).toString()
                frameAt = System.nanoTime(); seq++
            }
        } catch (_: Exception) {}
    }

    private fun r(v: Double?, n: Int): Any {
        if (v == null) return JSONObject.NULL
        val m = Math.pow(10.0, n.toDouble())
        return Math.round(v * m) / m
    }

    private fun frame(d: Map<String, Any?>, spd: Double, lg: Double, ok: Boolean, curMs: Int?, delta: Double?, vsTop: Double?, st: app.trace.telemetry.StintTracker.Snapshot?, car: String, track: String): JSONObject {
        val latG = (num(d["ang_y"]) * spd / 3.6 / 9.81).coerceIn(-4.0, 4.0)
        val sug = num(d["suggested_gear"]).toInt()
        fun arr(ks: List<String>, n: Int) = JSONArray().also { a -> ks.forEach { a.put(r(num(d[it]), n)) } }
        val hist = JSONArray().also { h -> laps.takeLast(8).forEach { h.put(JSONArray().put(it[0]).put(it[1])) } }
        val maxRpm = if (num(d["max_rpm"]) != 0.0) num(d["max_rpm"]) else num(d["rpm_limiter"])
        return JSONObject().put("type", "f").put("ok", ok).put("spd", r(spd, 1))
            .put("rpm", num(d["rpm"]).toInt()).put("maxrpm", maxRpm.toInt()).put("warnrpm", num(d["rpm_warning"]).toInt())
            .put("gear", num(d["gear"]).toInt()).put("sug", if (sug == 15) 0 else sug)
            .put("thr", r(num(d["throttle"]), 3)).put("brk", r(num(d["brake"]), 3)).put("str", r(num(d["steering"]), 3))
            .put("latg", r(latG, 2)).put("long", r(lg, 2))
            .put("tt", arr(listOf("tyre_temp_fl", "tyre_temp_fr", "tyre_temp_rl", "tyre_temp_rr"), 1))
            .put("ts", arr(listOf("tyre_slip_fl", "tyre_slip_fr", "tyre_slip_rl", "tyre_slip_rr"), 2))
            .put("fuel", r(num(d["fuel_remaining"]), 2)).put("cap", r(num(d["fuel_capacity"]), 2)).put("ev", d["is_ev"] as? Boolean ?: false)
            .put("lap", num(d["lap_number"]).toInt()).put("laps", num(d["total_laps"]).toInt())
            .put("cur", curMs ?: JSONObject.NULL).put("last", d["last_lap_ms"] ?: JSONObject.NULL).put("best", d["best_lap_ms"] ?: JSONObject.NULL)
            .put("delta", r(delta, 2)).put("top", r(vsTop, 2))
            .put("fl", r(st?.lapsOfFuel, 1)).put("fpl", r(st?.fuelPerLap, 2)).put("pit", st?.pitByLap ?: JSONObject.NULL)
            .put("spare", r(st?.spareLaps, 1)).put("stop", st?.stopNeeded ?: JSONObject.NULL).put("stint", st?.stintAge ?: JSONObject.NULL)
            .put("loss", r(st?.paceLossS, 2)).put("trend", r(st?.trendSPerLap, 2)).put("tyre", st?.tyreState ?: JSONObject.NULL)
            .put("car", clean(car)).put("track", clean(track))
            .put("pos", r(num(d["track_position"]), 1)).put("x", r(num(d["world_x"]), 1)).put("z", r(num(d["world_z"]), 1)).put("hdg", r(num(d["heading"]), 3))
            .put("tcs", d["tcs_active"] as? Boolean ?: false).put("asm", d["asm_active"] as? Boolean ?: false).put("lim", d["rev_limit_alert"] as? Boolean ?: false)
            .put("loss_pkt", JSONObject.NULL).put("hist", hist)
    }

    private fun trackMessage(): String {
        val (list, ver) = synchronized(lock) { pts.toList() to trackVersion }
        val step = maxOf(1, list.size / 700)
        val a = JSONArray()
        list.filterIndexed { i, _ -> i % step == 0 }.forEach { a.put(JSONArray().put(it.first).put(it.second)) }
        return JSONObject().put("type", "track").put("v", ver).put("pts", a).toString()
    }

    /** The current 6-digit code, "" while off. Shown in the Dashboard only, never logged. */
    val code: String get() = if (server != null) auth.code else ""
    val authRequired: Boolean get() = server != null && remote

    /** The link the Dashboard's QR encodes; a new one-time token once the last was used or is 5 minutes old. */
    fun qrUrl(host: String, port: Int): String = auth.qrToken().let { if (server != null && it.isNotEmpty()) "http://$host:$port/?t=$it" else "" }

    fun logoutAll() = auth.logoutAll()

    private fun needsAuth(c: Socket) = remote && !WebAuth.isLoopback(c.inetAddress)
    private fun authed(c: Socket, h: Map<String, String>) = !needsAuth(c) || auth.isAuthed(WebAuth.parseCookies(h["cookie"]))
    private fun sameOrigin(h: Map<String, String>): Boolean {
        val origin = h["origin"] ?: return true
        return origin.substringAfter("://").substringBefore('/').lowercase() == (h["host"] ?: "").lowercase()
    }
    private fun cookie(name: String, value: String, maxAge: Int? = null) =
        // Secure only over HTTPS; this server is plain HTTP on the LAN, so it is never set here.
        "Set-Cookie: $name=$value; Path=/; HttpOnly; SameSite=Strict" + (if (maxAge != null) "; Max-Age=$maxAge" else "")

    private fun readRequest(c: Socket): Triple<String, String, Map<String, String>>? {
        val inp = BufferedInputStream(c.getInputStream())
        val sb = StringBuilder()
        while (sb.length < 8192) {
            val b = inp.read(); if (b < 0) return null
            sb.append(b.toChar()); if (sb.endsWith("\r\n\r\n")) break
        }
        val lines = sb.toString().split("\r\n")
        val path = lines.firstOrNull()?.split(" ")?.getOrNull(1) ?: return null
        val h = HashMap<String, String>()
        for (l in lines.drop(1)) { val i = l.indexOf(':'); if (i > 0) h[l.substring(0, i).trim().lowercase()] = l.substring(i + 1).trim() }
        return Triple(path.substringBefore('?'), path.substringAfter('?', ""), h)
    }

    private fun respond(o: OutputStream, code: Int, phrase: String, body: ByteArray, ctype: String = "text/plain; charset=utf-8", extra: List<String> = emptyList()) {
        val csp = "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self' ws: wss:; font-src data:; img-src 'self' data:; manifest-src 'self'; " +
            "form-action 'self'; frame-ancestors 'none'; base-uri 'none'"
        o.write(("HTTP/1.1 $code $phrase\r\nContent-Type: $ctype\r\nContent-Length: ${body.size}\r\nCache-Control: no-store\r\n" +
            "X-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: $csp\r\n" +
            extra.joinToString("") { "$it\r\n" } + "Connection: close\r\n\r\n").toByteArray())
        o.write(body); o.flush()
    }
    private fun loginResponse(o: OutputStream) = respond(o, 401, "Unauthorized", loginPage(), "text/html; charset=utf-8")

    private fun send(o: OutputStream, text: String) {
        val b = text.toByteArray(); val h = java.io.ByteArrayOutputStream()
        h.write(0x81)
        when {
            b.size < 126 -> h.write(b.size)
            b.size < 65536 -> { h.write(126); h.write(b.size shr 8); h.write(b.size and 255) }
            else -> { h.write(127); for (i in 7 downTo 0) h.write(((b.size.toLong() shr (8 * i)) and 255).toInt()) }
        }
        o.write(h.toByteArray()); o.write(b); o.flush()
    }

    private fun handle(c: Socket) {
        var counted = false
        try {
            c.soTimeout = 10000
            val (path, query, h) = readRequest(c) ?: return
            val out = c.getOutputStream()
            val need = needsAuth(c)
            if (path == "/" || path == "/index.html") {
                val params = query.split('&').filter { it.isNotEmpty() }
                val tok = params.firstOrNull { it.substringBefore('=') == "t" }?.substringAfter('=', "")
                if (tok != null) {
                    if (need && !auth.consumeQr(URLDecoder.decode(tok, "UTF-8"))) { loginResponse(out); return }
                    // 302 to the same path WITHOUT the token so it never stays in history
                    val rest = params.filter { it.substringBefore('=') != "t" }.joinToString("&")
                    val extra = arrayListOf("Location: $path" + (if (rest.isNotEmpty()) "?$rest" else ""))
                    if (need) extra.add(cookie(WebAuth.SESSION_COOKIE, auth.newSession()))
                    respond(out, 302, "Found", ByteArray(0), extra = extra); return
                }
                if (!authed(c, h)) { loginResponse(out); return }
                respond(out, 200, "OK", page(), "text/html; charset=utf-8"); return
            }
            if (path == "/login") {
                if (!sameOrigin(h)) { respond(out, 403, "Forbidden", "Forbidden\n".toByteArray()); return }
                if (!need) { respond(out, 204, "No Content", ByteArray(0)); return }
                if (!auth.checkCode(c.inetAddress.hostAddress ?: "?", h["x-trace-code"])) {
                    respond(out, 401, "Unauthorized", "Wrong code or too many tries\n".toByteArray()); return
                }
                val extra = arrayListOf(cookie(WebAuth.SESSION_COOKIE, auth.newSession()))
                if (h["x-trace-remember"] == "1") extra.add(cookie(WebAuth.DEVICE_COOKIE, auth.rememberDevice(), WebAuth.DEVICE_DAYS * 86400))
                respond(out, 204, "No Content", ByteArray(0), extra = extra); return
            }
            // nothing -- not the feed, not even a 404 -- before the code
            if (!authed(c, h)) { loginResponse(out); return }
            if (path == "/session") { respond(out, 204, "No Content", ByteArray(0)); return }
            if (path == "/ws") {
                // a web page on another site must not be able to read the feed
                if (!sameOrigin(h)) { respond(out, 403, "Forbidden", "Forbidden\n".toByteArray()); return }
                val key = h["sec-websocket-key"]
                if (key == null) { respond(out, 400, "Bad Request", "Bad request\n".toByteArray()); return }
                if (clients.get() >= 16) { respond(out, 503, "Service Unavailable", "Too many viewers\n".toByteArray()); return }
                clients.incrementAndGet(); counted = true
                val acc = Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-1").digest((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").toByteArray()))
                out.write(("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: $acc\r\n" +
                    "X-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nReferrer-Policy: no-referrer\r\nCache-Control: no-store\r\n\r\n").toByteArray()); out.flush()
                c.soTimeout = 0
                send(out, "{\"type\":\"hello\",\"hz\":30}")
                var seen = -1; var tKey: Pair<Int, Int>? = null; var tSent = 0L; var idle = false; var checked = System.nanoTime()
                while (server != null && !c.isClosed) {
                    val now = System.nanoTime()
                    if (now - checked > 1_000_000_000L) {   // LOG OUT ALL DEVICES closes open feeds within a second
                        checked = now
                        if (!authed(c, h)) { out.write(byteArrayOf(0x88.toByte(), 0)); out.flush(); break }
                    }
                    val k = synchronized(lock) { trackVersion to pts.size / 20 }
                    if (k != tKey && (tKey == null || k.first != tKey.first || now - tSent > 2_000_000_000L)) { send(out, trackMessage()); tKey = k; tSent = now }
                    val (s, js, at) = synchronized(lock) { Triple(seq, json, frameAt) }
                    if (s != seen && js.isNotEmpty()) { seen = s; idle = false; send(out, js) }
                    else if (!idle && now - at > 1_500_000_000L) { idle = true; send(out, "{\"type\":\"idle\"}") }
                    Thread.sleep(33)
                }
                return
            }
            respond(out, 404, "Not Found", "Not found\n".toByteArray())
        } catch (_: Exception) {
        } finally {
            if (counted) clients.decrementAndGet()
            try { c.close() } catch (_: Exception) {}
        }
    }

    companion object {
        const val PORT = 8080
        fun lanIp(): String? = try {
            java.net.NetworkInterface.getNetworkInterfaces().toList().filter { it.isUp && !it.isLoopback }.flatMap { it.inetAddresses.toList() }
                .firstOrNull { it is java.net.Inet4Address && !it.isLoopbackAddress }?.hostAddress
        } catch (_: Exception) { null }
    }
}
